                if (active_iface.empty()) {
                    LOG_WARNING(LogModule::WEAK_MGR,
                                "no interface is currently using the network; "
                                "skipping this assessment round (no fabricated iface)");
                    // 与循环尾部同样的 100ms 分片等待：整段睡眠会让停止请求
                    // 最长等待一个完整 interval 才被响应。
