/// 运行时配置根结构。默认值 = 现有代码的硬编码（行为零变化基线）。
struct WeakNetConfig {
    /**
     * @brief eBPF Map 容量定标配置（config.yaml 扁平键 map_sizing_*）
     *
     * 三个键必须平铺而非嵌套：YAML 解析器只支持两层缩进。
     * 变更需 RestartMonitor 生效（不进 TRIAL 白名单，因为 map 已加载后无法 resize）。
     */
    struct MapSizingCfg {
        ConfigString mode{"auto"};                  ///< auto | fixed
        std::atomic<uint32_t> entries{0};           ///< fixed 生效；auto 下不参与计算
        std::atomic<uint32_t> ram_budget_bp{50};    ///< auto：物理内存的万分之几（50 = 0.5%）
    };

    // ---------- 服务端 ----------
    ConfigString data_dir{""};        ///< 空 → 走 WEAKNET_DATA_DIR / 内置默认
    ConfigString log_level{"info"};

    /**
     * @brief 配置代：任何一次成功的配置写入都会递增。
     *
     * 用途：已发布的 AssessmentSnapshot 带发布时的代次；代次不符即表示
     * 该快照基于旧配置，消费者必须按「过期」处理，不得继续返回旧结论。
     *
     * 由 setMonitorParam() 在写入成功后统一推进，因此本地 D-Bus 调参、
     * 云端下发与事务回滚三条路径都被覆盖，无需各调用点自己记账。
     */
    std::atomic<uint32_t> config_generation{1};

    // ---------- 传统监控线程 ----------
    struct {
        std::atomic<bool> enabled{true};
        ConfigString target{"223.5.5.5"};
        std::atomic<uint32_t> interval_ms{10000};
        std::atomic<uint32_t> timeout_ms{800};
        /// RTT 样本滑动窗口大小（样本数），用于在 rtt 监控线程内计算 Jitter。
        /// <=0 表示不启用抖动统计；原独立 jitter_monitor 已合并进 rtt_monitor。
        std::atomic<uint32_t> window_size{30};
    } rtt;

    // 抖动（Jitter）不再是独立监控项：作为 RTT 的衍生指标，
    // 由 rtt_monitor 在同一次 ping 采样上直接计算滑动窗口标准差。

    struct {
        std::atomic<bool> enabled{true};
        std::atomic<uint32_t> interval_ms{10000};
    } rssi;

    struct {
        std::atomic<bool> enabled{true};
        std::atomic<uint32_t> interval_ms{10000};
    } tcp_loss;

    struct {
        std::atomic<bool> enabled{true};
        std::atomic<uint32_t> interval_ms{10000};
    } traffic;

    struct {
        std::atomic<bool> enabled{true};
        std::atomic<uint32_t> interval_ms{15000};
    } quality;

    struct {
        std::atomic<bool> enabled{true};
        std::atomic<uint32_t> interval_ms{3000};
        ConfigString bpf_obj{"build/a2dp_media.bpf.o"};   ///< Phase2 eBPF 融合层对象（legacy A2DP）
        /// 旧 A2DP 音频探针开关：工业蓝牙 HCI ACL 新探针（bt_hci_traffic）验收通过后
        /// 默认停用，避免两套采集链同时挂在内核上重复统计/增加开销；保留配置键、
        /// bt_history 表与 GetBluetoothAudioQuality 接口兼容，需要时可显式开回。
        std::atomic<bool> a2dp_fusion_enabled{false};
        MapSizingCfg map_sizing;                          ///< a2dp LRU map 定标
        /// Phase 1 设备事件采集器对象（bt_events.bpf.o）。
        /// 与 a2dp_media 是**两条独立的数据路径**：a2dp 走 map 累计音频流量，
        /// bt_events 走 ringbuf 上报断连事件。前者是 legacy 音频能力，
        /// 后者是工业无线诊断的主线。
        ConfigString events_bpf_obj{"build/bt_events.bpf.o"};

        /// Phase 1 HCI ACL 工业数据通道流量探针对象（bt_hci_traffic.bpf.o）

