/**
 * @file host_pressure_monitor.hpp
 * @brief 采集端自身 CPU 压力监控器
 *
 * 目的不是"多采一个指标"，而是补上证据链里的一个真实漏洞：
 *
 *   现有 Observer 质量判定只看 eBPF 的 capture_emit_failure_ratio。
 *   但"BPF 掉证据"有两个完全不同的成因：
 *     (a) 网络/内核真的出了问题
 *     (b) 板子 CPU 被打满，采集线程抢不到 CPU，perf buffer 来不及消费
 *   旧证据无法区分这两者，于是 (b) 会被误判成网络故障。
 *
 * 本监控器把"观测者自身状态"变成可判定的证据，让归因能往下分辨一层。
 *
 * 数据来源是 kmod/weaknet_cpu_stat：内核 hrtimer 每 4 ms 采集一次
 * per-CPU 累计时间（user/nice/system/idle/iowait/irq/softirq/steal），
 * 通过 /dev/weaknet_cpu_stat 只读 mmap 暴露，seqlock 保证一致性。
 * 该模块已实测 30 分钟长稳：5851 万次读取零失败、进程 RSS 零增长。
 *
 * 重要语义边界（不要越过）：
 *   CPU 忙 只能说明"采集端可能来不及处理"，不能说明"网络坏了"，
 *   也不能说明"网络没坏"。它是**归因辅助证据**，不是故障判据本身。
 */

#pragma once

#include <cstdint>
#include <string>
#include <thread>
#include <vector>

namespace weaknet_dbus {

class ServerContext;

/**
 * @brief 一次 CPU 压力采样结果
 */
struct HostCpuPressure {
    /// 本轮是否得到了可用的比率。false 时 @busy_ratio 无意义，
    /// 且必须把对应指标发布为 UNAVAILABLE —— 绝不伪造 0。
    bool available{false};

    /// 全系统 CPU 忙碌占比 0~1。
    ///
    /// 多核**按累计时间加权**（sum(busy)/sum(total)），不是各核比率的算术平均。
    /// 差异是实质性的：8 核里 1 核 100% 其余空闲，加权得 0.125，
    /// 算术平均也得 0.125 —— 但当各核 total 不等（部分核被隔离或 tickless）时
    /// 两者会分叉，加权才是"系统整体花了多少时间在忙"的正确语义。
    double busy_ratio{0.0};

    /// 参与本轮差值的 CPU 数量（已排除离线与累计值被重置的核）
    uint32_t sampled_cpus{0};

    /// 系统在线 CPU 总数（含本轮未参与差值的）
    uint32_t online_cpus{0};

    /// available=false 时的机器可读原因，如 "device_absent" / "baseline_only"
    std::string reason;
};

/**
 * @brief CPU 压力采样器
 *
 * 有状态：需要保留上一份快照才能做区间差值。
 *
 * 为什么必须做差值而不是直接用累计值：
 *   /dev/weaknet_cpu_stat 发布的是**自开机以来的累计纳秒**。
 *   直接用它算比率会得到"开机至今的平均负载"，一个持续了十小时的开机
 *   过程中的瞬时尖峰会被完全抹平，用来判断"这一轮评估期间采集端是否过载"
 *   就毫无意义。只有相邻两次采样的差值才反映当前这段区间。
 *
 * 线程安全：非线程安全。同一个实例只应由一个线程持有使用。
 */
class HostCpuPressureSampler {
public:
    explicit HostCpuPressureSampler(std::string dev_path = "/dev/weaknet_cpu_stat");

    /**
     * @brief 采一次样并与上一样本做差值
     *
     * 首次调用只建立基线，返回 available=false, reason="baseline_only"。
     * 这是刻意行为：没有前一份样本时任何比率都是凭空捏造。
     */
    HostCpuPressure sample();

    const std::string& devPath() const { return dev_path_; }

private:
    /// 单 CPU 的时间累计（纳秒），字段与 ABI 头 struct wn_cpu_stat 一一对应。
    /// 这里刻意不直接复用内核头，避免服务端源码对内核 ABI 布局产生编译期耦合；
    /// 两者的一致性由 test_host_pressure_monitor_gtest 的尺寸/偏移断言守住。
    struct CpuTimes {
        uint32_t cpu_id{0};
        bool online{false};
        bool valid{false};
        uint64_t user{0};
        uint64_t nice{0};
        uint64_t system{0};
        uint64_t idle{0};
        uint64_t iowait{0};
        uint64_t irq{0};
        uint64_t softirq{0};
        uint64_t steal{0};
        uint64_t guest{0};
        uint64_t guest_nice{0};

        /// 与 /proc/stat 同口径：guest 已含在 user 内，不再重复计入 busy。
        uint64_t busy() const {
            return user + nice + system + irq + softirq + steal;
        }
        uint64_t total() const { return busy() + idle + iowait; }
    };

    /// 读一份快照。成功返回 true 并填充 out；失败返回 false 并填 reason。
    bool readSnapshot(std::vector<CpuTimes>* out, std::string* reason);

    std::string dev_path_;
    std::vector<CpuTimes> prev_;
    bool have_prev_{false};
};

/**
 * @brief 启动 CPU 压力监控线程
 *
 * 循环内每轮从线程安全配置现读 interval，支持 D-Bus 实时调参。
 * 采样结果通过 MetricsRegistry::publishScope(MetricScope::HOST, ...) 发布，
 * 命名空间键为 "host:"（见 metrics_registry.hpp 的 scopeKey）。
 */
void start_host_pressure_monitor_thread(ServerContext* ctx, std::thread* worker);

}  // namespace weaknet_dbus

