static bool applyMonitorParam(WeakNetConfig* cfg, const std::string& key,
                       const std::string& value, std::string* error) {
    if (!cfg) return false;
    std::string mon, field;
    if (!splitMonitorKey(key, &mon, &field)) {
        if (error) *error = "invalid key format (expected 'monitor.field'): " + key;
        return false;
    }

    // 先校验，再原子提交（先在局部变量跑完所有校验，最后一次性写回）
    if (mon == "rtt") {
        if (field == "enabled") { bool b; if (!parseBool(value, &b)) { if (error) *error = "rtt.enabled: invalid bool"; return false; } cfg->rtt.enabled.store(b); return true; }
        if (field == "target") { if (!isValidIPv4(trim(value))) { if (error) *error = "rtt.target: invalid IPv4"; return false; } cfg->rtt.target.set(trim(value)); return true; }
        if (field == "interval" || field == "interval_ms") { uint32_t ms; if (!parseDurationMs(value, &ms) || !checkRange(ms, 100, 600000)) { if (error) *error = "rtt.interval: must be 100ms~600000ms"; return false; } cfg->rtt.interval_ms.store(ms); return true; }
        if (field == "timeout" || field == "timeout_ms") { uint32_t ms; if (!parseDurationMs(value, &ms) || !checkRange(ms, 100, 60000)) { if (error) *error = "rtt.timeout: must be 100ms~60000ms"; return false; } cfg->rtt.timeout_ms.store(ms); return true; }
        if (field == "window" || field == "window_size") { uint32_t w; if (!parseUint(value, &w) || !checkRange(w, 2, 1000)) { if (error) *error = "rtt.window_size: must be 2~1000"; return false; } cfg->rtt.window_size.store(w); return true; }
    }
    // jitter 已合并进 rtt：抖动不再作为独立监控项下发参数，
    // 调参入口改为 rtt.window_size / rtt.interval_ms 等。
    if (mon == "rssi") {
        if (field == "enabled") { bool b; if (!parseBool(value, &b)) { if (error) *error = "rssi.enabled: invalid bool"; return false; } cfg->rssi.enabled.store(b); return true; }
        if (field == "interval" || field == "interval_ms") { uint32_t ms; if (!parseDurationMs(value, &ms) || !checkRange(ms, 1000, 600000)) { if (error) *error = "rssi.interval: must be 1000ms~600000ms"; return false; } cfg->rssi.interval_ms.store(ms); return true; }
    }
    if (mon == "tcp_loss") {
        if (field == "enabled") { bool b; if (!parseBool(value, &b)) { if (error) *error = "tcp_loss.enabled: invalid bool"; return false; } cfg->tcp_loss.enabled.store(b); return true; }
        if (field == "interval" || field == "interval_ms") { uint32_t ms; if (!parseDurationMs(value, &ms) || !checkRange(ms, 1000, 600000)) { if (error) *error = "tcp_loss.interval: must be 1000ms~600000ms"; return false; } cfg->tcp_loss.interval_ms.store(ms); return true; }
    }
    if (mon == "traffic") {
        if (field == "enabled") { bool b; if (!parseBool(value, &b)) { if (error) *error = "traffic.enabled: invalid bool"; return false; } cfg->traffic.enabled.store(b); return true; }
        if (field == "interval" || field == "interval_ms") { uint32_t ms; if (!parseDurationMs(value, &ms) || !checkRange(ms, 1000, 600000)) { if (error) *error = "traffic.interval: must be 1000ms~600000ms"; return false; } cfg->traffic.interval_ms.store(ms); return true; }
    }
    if (mon == "quality") {
        if (field == "enabled") { bool b; if (!parseBool(value, &b)) { if (error) *error = "quality.enabled: invalid bool"; return false; } cfg->quality.enabled.store(b); return true; }
        if (field == "interval" || field == "interval_ms") { uint32_t ms; if (!parseDurationMs(value, &ms) || !checkRange(ms, 1000, 600000)) { if (error) *error = "quality.interval: must be 1000ms~600000ms"; return false; } cfg->quality.interval_ms.store(ms); return true; }
    }
    if (mon == "bluetooth") {
        if (field == "enabled") { bool b; if (!parseBool(value, &b)) { if (error) *error = "bluetooth.enabled: invalid bool"; return false; } cfg->bluetooth.enabled.store(b); return true; }
        if (field == "interval" || field == "interval_ms") { uint32_t ms; if (!parseDurationMs(value, &ms) || !checkRange(ms, 1000, 60000)) { if (error) *error = "bluetooth.interval: must be 1000ms~60000ms"; return false; } cfg->bluetooth.interval_ms.store(ms); return true; }
        if (isMapSizingField(field)) return setMapSizingField(cfg->bluetooth.map_sizing, field, value, "bluetooth", error);
        if (field == "bpf_obj") { cfg->bluetooth.bpf_obj.set(trim(value)); return true; }
        if (field == "a2dp_fusion_enabled") { bool b; if (!parseBool(value, &b)) { if (error) *error = "bluetooth.a2dp_fusion_enabled: invalid bool"; return false; } cfg->bluetooth.a2dp_fusion_enabled.store(b); return true; }
        if (field == "events_bpf_obj") { cfg->bluetooth.events_bpf_obj.set(trim(value)); return true; }
        if (field == "hci_traffic_bpf_obj") { cfg->bluetooth.hci_traffic_bpf_obj.set(trim(value)); return true; }
        // Phase 3a 区域关联阈值。范围校验与 yaml 加载路径一致；这些键改完需
        // `monitor restart bt_events` 生效（关联器配置构造期冻结）。
        if (field == "incident_min_devices") { uint32_t v; if (!parseUint(value, &v) || !checkRange(v, 2, 1000)) { if (error) *error = "bluetooth.incident_min_devices: must be 2~1000"; return false; } cfg->bluetooth.incident_min_devices.store(v); return true; }
        if (field == "incident_min_ratio_bp") { uint32_t v; if (!parseUint(value, &v) || !checkRange(v, 1, 10000)) { if (error) *error = "bluetooth.incident_min_ratio_bp: must be 1~10000 (basis points)"; return false; } cfg->bluetooth.incident_min_ratio_bp.store(v); return true; }
        if (field == "incident_window" || field == "incident_window_ms") { uint32_t ms; if (!parseDurationMs(value, &ms) || !checkRange(ms, 1000, 600000)) { if (error) *error = "bluetooth.incident_window: must be 1s~10m"; return false; } cfg->bluetooth.incident_window_ms.store(ms); return true; }
        if (field == "incident_quiet_window" || field == "incident_quiet_window_ms") { uint32_t ms; if (!parseDurationMs(value, &ms) || !checkRange(ms, 1000, 86400000)) { if (error) *error = "bluetooth.incident_quiet_window: must be 1s~24h"; return false; } cfg->bluetooth.incident_quiet_window_ms.store(ms); return true; }
        if (field == "incident_active_window" || field == "incident_active_window_ms") { uint32_t ms; if (!parseDurationMs(value, &ms) || !checkRange(ms, 1000, 600000)) { if (error) *error = "bluetooth.incident_active_window: must be 1s~10m"; return false; } cfg->bluetooth.incident_active_window_ms.store(ms); return true; }
        // Phase 2 蓝牙数据通道异常规则阈值
        if (field == "stall_timeout" || field == "stall_timeout_ms") { uint32_t ms; if (!parseDurationMs(value, &ms) || !checkRange(ms, 0, 600000)) { if (error) *error = "bluetooth.stall_timeout: must be 0~10m"; return false; } cfg->bluetooth.stall_timeout_ms.store(ms); return true; }
        if (field == "stall_consecutive_windows") { uint32_t w; if (!parseUint(value, &w) || !checkRange(w, 1, 100)) { if (error) *error = "bluetooth.stall_consecutive_windows: must be 1~100"; return false; } cfg->bluetooth.stall_consecutive_windows.store(w); return true; }
        if (field == "min_expected_bps") { uint32_t bps; if (!parseUint(value, &bps)) { if (error) *error = "bluetooth.min_expected_bps: invalid integer"; return false; } cfg->bluetooth.min_expected_bps.store(bps); return true; }
        if (field == "degraded_consecutive_windows") { uint32_t w; if (!parseUint(value, &w) || !checkRange(w, 1, 100)) { if (error) *error = "bluetooth.degraded_consecutive_windows: must be 1~100"; return false; } cfg->bluetooth.degraded_consecutive_windows.store(w); return true; }
    }
    if (mon == "dns") {
        if (field == "enabled") { bool b; if (!parseBool(value, &b)) { if (error) *error = "dns.enabled: invalid bool"; return false; } cfg->dns.enabled.store(b); return true; }
        if (field == "bpf_obj") { cfg->dns.bpf_obj.set(trim(value)); return true; }

